; psg.asm -- chapter 3: the PSG's sixteen registers, as left and as written
; generated by gen03.py
        INCLUDE "msx.inc"
        OUTPUT "psg.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
before  EQU VARS + 16           ; the registers as the BIOS left them
after   EQU VARS + 32           ; and after $FF was written to each
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld hl, before           ; read all sixteen before touching any
        call readall
        ld a, 7                 ; the mixer first: every tone and noise off,
        out (PSG_ADDR), a       ; port A an input, port B an output
        ld a, $BF
        out (PSG_WRITE), a
        ld e, 0                 ; then $FF into every other register but 14
.wr:    ld a, e
        cp 7
        jr z, .skip
        cp 14
        jr z, .skip
        out (PSG_ADDR), a
        ld a, $FF
        out (PSG_WRITE), a
.skip:  inc e
        ld a, e
        cp 16
        jr nz, .wr
        ld hl, after
        call readall
        ld a, 8                 ; silence: the three volumes back to 0
        call zero
        ld a, 9
        call zero
        ld a, 10
        call zero
        ld b, 1
        ld c, 0
        ld hl, t_num
        call puts
        ld b, 2
        ld c, 0
        ld hl, t_before
        call puts
        ld hl, before
        ld b, 3
        ld c, 0
        call regs8
        ld b, 5
        ld c, 0
        call regs8
        ld b, 8
        ld c, 0
        ld hl, t_after
        call puts
        ld hl, after
        ld b, 9
        ld c, 0
        call regs8
        ld b, 11
        ld c, 0
        call regs8
        VDP_REG 1, $C0          ; display on: the page is finished
done:   jr done

; readall: the sixteen registers into 16 bytes from HL
readall:
        ld e, 0
.r:     ld a, e
        out (PSG_ADDR), a
        in a, (PSG_READ)
        ld (hl), a
        inc hl
        inc e
        ld a, e
        cp 16
        jr nz, .r
        ret

; zero: register A := 0
zero:   out (PSG_ADDR), a
        xor a
        out (PSG_WRITE), a
        ret

; regs8: 8 bytes from HL, two hexadecimal digits and a space each
regs8:  ld e, 8
.n:     ld a, (hl)
        call puthex
        inc c
        inc c
        inc hl
        dec e
        jr nz, .n
        ret

t_num:  db "R0-R7, then R8-R15", 0
t_before: db "as the BIOS left them:", 0
t_after: db "after writing $FF:", 0

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
